-- Create base lookup/independent tables first
CREATE TABLE public.categories (
    "CategoryID" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "CategoryName" text NOT NULL,
    CONSTRAINT categories_pkey PRIMARY KEY ("CategoryID")
);

CREATE TABLE public.users (
    "UserID" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "UserName" text NOT NULL,
    "UserPass" text NOT NULL,
    CONSTRAINT users_pkey PRIMARY KEY ("UserID")
);

CREATE TABLE public."expenseTypes" (
    "TypeID" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "TypeName" text NOT NULL,
    CONSTRAINT "expenseTypes_pkey" PRIMARY KEY ("TypeID")
);

CREATE TABLE public.stores (
    "StoreID" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "StoreName" text NOT NULL,
    "NIF" text DEFAULT ''::text,
    CONSTRAINT stores_pkey PRIMARY KEY ("StoreID")
);

-- Create main expenses table including the 'qr' column
CREATE TABLE public.expenses (
    "ExpID" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "Description" text NOT NULL,
    "Value" numeric(12,2) DEFAULT 0 NOT NULL,
    "StoreID" integer DEFAULT 0 NOT NULL,
    "CategoryID" integer DEFAULT 0 NOT NULL,
    "OwnerUserID" integer DEFAULT 0 NOT NULL,
    "TypeID" integer DEFAULT 0 NOT NULL,
    "ExpDate" timestamp without time zone NOT NULL,
    "CreationDate" timestamp without time zone NOT NULL,
    "PaidOff" boolean DEFAULT false,
    "SharesEven" boolean DEFAULT false,
    qr text DEFAULT ''::text,
    CONSTRAINT expenses_pkey PRIMARY KEY ("ExpID"),
    CONSTRAINT "expenses_StoreID_fkey" FOREIGN KEY ("StoreID") REFERENCES public.stores("StoreID") ON DELETE RESTRICT,
    CONSTRAINT "expenses_CategoryID_fkey" FOREIGN KEY ("CategoryID") REFERENCES public.categories("CategoryID") ON DELETE RESTRICT,
    CONSTRAINT "expenses_OwnerUserID_fkey" FOREIGN KEY ("OwnerUserID") REFERENCES public.users("UserID") ON DELETE RESTRICT,
    CONSTRAINT "expenses_TypeID_fkey" FOREIGN KEY ("TypeID") REFERENCES public."expenseTypes"("TypeID") ON DELETE RESTRICT
);

-- Create dependent relationship tables
CREATE TABLE public."expensesPayments" (
    "ExpPaymID" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "ExpID" integer NOT NULL,
    "UserID" integer NOT NULL,
    "Payed" numeric(12,2) DEFAULT 0 NOT NULL,
    CONSTRAINT "expensesPayments_pkey" PRIMARY KEY ("ExpPaymID"),
    CONSTRAINT "expensesPayments_ExpID_fkey" FOREIGN KEY ("ExpID") REFERENCES public.expenses("ExpID") ON DELETE RESTRICT,
    CONSTRAINT "expensesPayments_UserID_fkey" FOREIGN KEY ("UserID") REFERENCES public.users("UserID") ON DELETE RESTRICT
);

CREATE TABLE public."expensesShares" (
    "ExpShareID" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "ExpID" integer NOT NULL,
    "UserID" integer NOT NULL,
    "Share" numeric(6,2) DEFAULT 0.5 NOT NULL,
    "Calculated" numeric(12,2) DEFAULT 0 NOT NULL,
    CONSTRAINT "expensesShares_pkey" PRIMARY KEY ("ExpShareID"),
    CONSTRAINT "expensesShares_ExpID_fkey" FOREIGN KEY ("ExpID") REFERENCES public.expenses("ExpID") ON DELETE RESTRICT,
    CONSTRAINT "expensesShares_UserID_fkey" FOREIGN KEY ("UserID") REFERENCES public.users("UserID") ON DELETE RESTRICT
);
